mapper.select:
select vh.*, u.username as user_name, COALESCE(( select count(*) from user_collect uc where uc.target_type = 'homestay' and uc.target_id = CAST(vh.id AS CHAR) ), 0) as collect_number, -- is_collect 表示"当前用户是否收藏过"，依赖传入的 userId CASE WHEN #{userId} IS NOT NULL AND EXISTS ( SELECT 1 FROM user_collect uc2 WHERE uc2.user_id = #{userId} AND uc2.target_type = 'homestay' AND uc2.target_id = CAST(vh.id AS CHAR) ) THEN 1 ELSE 0 END AS is_collect from village_homestay vh LEFT JOIN sys_user u ON vh.user_id = u.id
and vh.user_id = #{merchantUserId}
and vh.village_id = #{villageId}
and vh.homestay_name like concat('%', #{homestayName}, '%')
and vh.address like concat('%', #{address}, '%')
and vh.status = #{status}
and vh.star_level = #{starLevel}
and vh.contact_name like concat('%', #{contactName}, '%')
and (vh.homestay_name like concat('%', #{keyword}, '%') or vh.address like concat('%', #{keyword}, '%') or vh.contact_name like concat('%', #{keyword}, '%'))
order by vh.id asc

