update village_homestay
user_id = #{userId}, village_id = #{villageId}, homestay_name = #{homestayName}, address = #{address}, status = #{status}, star_level = #{starLevel}, room_count = #{roomCount}, bed_count = #{bedCount}, max_capacity = #{maxCapacity}, contact_name = #{contactName}, contact_phone = #{contactPhone}, description = #{description}, cover_image = #{coverImage}, latitude = #{latitude}, longitude = #{longitude}, qualification_images = #{qualificationImages}, link_address = #{linkAddress}, update_time = now()
